    /**
     * The link frame at the read.
     */
    val frame: Long,
    /**
     * The unit's clock at the read, µs (wraps).
     */
    val timeUs: Long,
    /**
     * Output frames played, low 32 bits.
     */
    val outputFrames: Long,
)

/**
 * What `EXT_APPLY_AT_FRAME` reports: the unit's queue of ops.
 */
data class ApplyAtFrameStatus(
    /**
     * Ops waiting for their frame (at most 4).
     */
    val pending: Int,
    /**
     * The last op: `cancel_all`, `mute`, `unmute`, `preset_load`,
     * `master_volume`, `out_delay`, `rate`, `click`, `sync_pulse`.
     */
    val lastOp: String,
    /**
     * Its code.
     */
    val lastOpCode: Int,
    /**
     * How it ended: `applied`, `late`, `cancelled`, `refused`.
     */
    val lastResult: String,
    /**
     * Its code.
     */
    val lastResultCode: Int,
    /**
     * The frame it ran at.
     */
    val lastFrame: Long,
)

/**
 * One GET the host is asked to make.
 */
data class AutoEqFetchRequest(
    /**
     * The URL, already percent-encoded.
     */
    val url: String,
    /**
     * The `Accept` header to send, if any.
     */
    val accept: String?,
    /**
     * The `User-Agent` header to send. GitHub refuses a request without one.
     */
    val userAgent: String,
)

/**
 * What the server answered, whatever the status: a 403 or a 500 is an answer.
 */
data class AutoEqFetchResponse(
    /**
     * The HTTP status, after following redirects.
     */
    val status: Int,
    /**
     * The body, as received. Pass it for an error status too.
     */
    val body: List<Int>,
    /**
     * The `Retry-After` header in seconds; `None` if absent or a date.
     */
    val retryAfterS: Long?,
    /**
     * The `X-RateLimit-Remaining` header.
     */
    val rateLimitRemaining: Long?,
    /**
     * The `X-RateLimit-Reset` header, in Unix seconds.
     */
    val rateLimitReset: Long?,
)

/**
 * What the "Update Database" dialog shows about the database in place.
 */
data class AutoEqDatabaseInfo(
    /**
     * A user database is at `db_path`, which is what decides whether "Reset to
     * Built-in" is offered. True for a damaged file too, so it can be reset.
     */
    val hasUserDatabase: Boolean,
    /**
     * Why the file could not be read; `None` if it could, or there is none.
     */
    val problem: String?,
    /**
     * The file's format version; 0 with no readable database.
     */
    val version: Int,
    /**
     * When it was generated, ISO 8601 as the file has it; empty if unknown. An
     * imported file can say anything here: show it as text if it does not parse.
     */
    val generatedAt: String,
    /**
     * Profiles it holds.
     */
    val entryCount: Long,
)

/**
 * Where a rebuild has got to, from [`AutoEqRebuild::poll`].
 */
data class AutoEqRebuildProgress(
    /**
     * 0.0 to 1.0.
     */
    val fraction: Float,
    /**
     * A line for the progress dialog; once finished, the result in words.
     */
    val status: String,
    /**
     * The rebuild is over, one way or the other; the fields below are final.
     */
    val finished: Boolean,
    /**
     * The database was written. It may still have parts missing: see
     * `failed_profiles` and `failed_listings`. On a failure the file was left
     * as it was.
     */
    val succeeded: Boolean,
    /**
     * Once finished without success, why: `cancelled`, or an
     * [`AutoEq`](DspiError::AutoEq) code; empty otherwise.
     */
    val code: String,
    /**
     * With `code` `rate_limited`: seconds until it is worth trying again, when
     * the server said.
     */
    val retryAfterS: Long?,
    /**
     * Profiles in the database written.
     */
    val entries: Long,
    /**
     * Profiles that should have come and did not. Tell the person.
     */
    val failedProfiles: Long,
    /**
     * Directory listings that failed, whose profiles were never seen. Tell the
     * person.
     */
    val failedListings: Long,
    /**
     * Folders with no usable profile, which is normal upstream.
     */
    val skippedProfiles: Long,
)

/**
 * What `EXT_IDENTIFY` reports: the blink state and what the board is.
 */
data class IdentifyInfo(
    /**
     * Blink time left in seconds, rounded up; 0 when not blinking.
     */
    val remainingS: Int,
    /**
     * The output of the last identify tone since the device started.
     */
    val lastToneOutput: Int?,
    /**
     * `RP2040` or `RP2350` (`chip N` for a value this build does not know).
     */
    val chip: String,
    /**
     * The SDK's chip revision number.
     */
    val chipRev: Int,
    /**
     * The raw `SYSINFO.CHIP_ID` register.
     */
    val chipId: Long,
    /**
     * The board the firmware was built for (`pico`, `pico2`).
     */
    val board: String,
    /**
     * The hardware revision the firmware build was given; empty when the
     * build set none (the firmware cannot sense it).
     */
    val hwRev: String,
)

/**
 * What `EXT_RESET_INFO` reports: why the device last restarted.
 */
data class DeviceResetInfo(
    /**
     * A stable name: `power_on`, `brownout`, `run_pin`, `watchdog`,
     * `software`, `debugger`, `glitch` or `unknown`.
     */
    val reason: String,
    /**
     * The firmware's reason code (reset_info.h), for a code this build does
     * not know too.
     */
    val reasonCode: Int,
    /**
     * The reason in words.
     */
    val description: String,
    /**
     * Seconds since that restart.
     */
    val uptimeS: Long,
    /**
     * How long the run before it lasted, in seconds; `None` after a power-on
     * or a brown-out, which clear the record.
     */
    val prevUptimeS: Long?,
    /**
     * Watchdog hangs this power session not yet acted on (the core voltage
     * extension's count).
     */
    val hangCount: Int,
    /**
     * `RP2040` or `RP2350`.
     */
    val chip: String,
    /**
     * The raw reset-cause register at boot, for a support report.
     */
    val chipReset: Long,
    /**
     * The raw `WATCHDOG.REASON` at boot (bit 8: the firmware's own timeout).
     */
    val watchdogReason: Long,
)

/**
 * What a board needs, read before it enters the bootloader. The default is
 * the safe one: unknown.
 */
data class FirmwareGuardBoard(
    /**
     * The lowest core voltage this board may be left on, in mV. 1150: not at
     * risk. Above that: at risk. Anything else, 0 included: unknown.
     */
    val requiredMv: Int,
    /**
     * Where it came from.
     */
    val source: FirmwareGuardBoardSource,
)

/**
 * The result of [`firmware_guard_check`]. The default blocks.
 */
data class FirmwareGuardVerdict(
    /**
     * True only for `Clear` and `Confirmed`. Anything else must not flash.
     */
    val allowed: Boolean,
    /**
     * The decision.
     */
    val decision: FirmwareGuardDecision,
    /**
     * Why.
     */
    val reason: FirmwareGuardReason,
    /**
     * For the user, in English.
     */
    val message: String,
    /**
     * What to ask the user to type when a risk is involved, else "": the
     * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
     * exactly: case and spaces count, and the one does not stand for the other.
     */
    val confirmationPhrase: String,
    /**
     * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
     */
    val imageMv: Int,
    /**
     * The board record's `required_mv`, as given.
     */
    val requiredMv: Int,
)

/**
 * One change in the history ([`DspiCore::history`]).
 */
data class HistoryEntry(
    /**
     * The registry path (`out.gain`, `eq.freq`, ...), or one of the
     * journal's own: `eq.band` (a whole band: type, bypass, then freq, Q,
     * gain and the Linkwitz target Q as little-endian `f32`s), `ext.pairmap`
     * (the crossfeed pair map's four bytes), `ext.vreg` (a core-voltage
     * request: op and value), `raw` (a raw request: opcode and `wValue` as
     * indices, the payload as the value), `ext.audio_link.slots` (the 8
     * slot bytes), `ext.audio_link.phase` (mode, then the delay and the
     * hops offset as little-endian 16-bit values), `ext.audio_link.apply`
     * (op and arg as indices, the 16-byte request as the value) and
     * `ext.audio_link.stats_reset`. A control-surface operation is
     * under its `cs.*` path with the operation's JSON as text.
     */
    val path: String,
    /**
     * The path's indices (an output, a channel and a band, ...).
     */
    val indices: List<Int>,
    /**
     * The value before, when known; undo writes it back.
     */
    val before: ParamValue?,
    /**
     * The value after (`trigger` for an action).
     */
    val after: ParamValue,
    /**
     * Who made it.
     */
    val source: HistorySource,
    /**
     * When, in milliseconds since the Unix epoch (a drag: its last step).
     */
    val atMs: Long,
    /**
     * Whether undo may reverse it. The registry decides: only a parameter
     * with no hazard (not a flash write, an audible one, a reconfiguration,
     * a deferred or an irreversible one).
     */
    val undoable: Boolean,
)

/**
 * What [`DspiCore::undo`] or [`DspiCore::redo`] did.
 */
data class HistoryMove(
    /**
     * The change reversed (undo) or applied again (redo); `None` when
     * nothing moved.
     */
    val entry: HistoryEntry?,
    /**
     * The changes stepped over on the way, newest first, which cannot be
     * undone (see [`HistoryEntry::undoable`]). An entry here that is
     * undoable had no value before to restore, or someone else has changed
     * it since (`note` says who); the walk stopped there. A drag's step of
     * several values lists here each value someone else changed since, one
     * entry each, also when its other values moved.
     */
    val skipped: List<HistoryEntry>,
    /**
     * Why a value was left alone, in words, when another writer changed it
     * since (only where the core leaves such a change alone): nothing moved,
     * or, for a drag's step of several values, the others did. `None`
     * otherwise.
     */
    val note: String?,
)

/**
 * One element of the installation: the sender, a fan-out or a unit.
 */
data class LinkSystemUnit(
    /**
     * The model's id.
     */
    val id: String,
    /**
     * Its name, or the id when it has none.
     */
    val name: String,
    /**
     * The device's serial; "" when the model has none.
     */
    val serial: String,
    /**
     * `sender`, `fan_out` or `unit`.
     */
    val kind: String,
    /**
     * The role on the audio link in the glossary's words: "Sender",
     * "Fan-out", "Repeater", "Receiver" (what the device says, else the model),
     * or "No audio link" for a device whose firmware has none (WP HWLK1F).
     */
    val role: String,
    /**
     * The room's name; "" for none.
     */
    val room: String,
    /**
     * Attached to the hub now.
     */
    val connected: Boolean,
    /**
     * `locked`, `searching`, `holdover`, `off`, `clock` (a sender),
     * `offline` (not attached), `no_alink` (attached, its firmware has no
     * audio link: WP HWLK1F) or `unknown`.
     */
    val state: String,
    /**
     * [`Self::state`] in words: "Locked", "Holdover", ... "Not connected".
     */
    val stateWord: String,
    /**
     * The unit's link delay or hop offset is not the one the system delay
     * asks for: writing the link delays ([`DspiCore::link_system_align`])
     * is pending.
     */
    val pending: Boolean,
    /**
     * The link delay the alignment asks for, frames; else the unit's own.
     */
    val linkDelayFrames: Long?,
    /**
     * [`Self::link_delay_frames`] in ms at the system's rate.
     */
    val linkDelayMs: Double?,
    /**
     * The link delay the unit has now, frames, when it reported one.
     */
    val unitLinkDelayFrames: Long?,
    /**
     * The shortest link delay the unit takes, frames.
     */
    val linkDelayMin: Long?,
    /**
     * The longest.
     */
    val linkDelayMax: Long?,
    /**
     * The hop offset the alignment asks for, frames; else the unit's own.
     */
    val hopOffset: Int?,
    /**
     * The hop offset the unit has now.
     */
    val unitHopOffset: Int?,
    /**
     * The phase error, frames (phase lock).
     */
    val phaseErrorFrames: Float?,
    /**
     * Fan-outs and repeaters between the sender and this unit.
     */
    val hops: Long?,
    /**
     * Frames a fan-out or repeater adds passing the stream on.
     */
    val hopDelayFrames: Long?,
    /**
     * The output latency the model counts, µs.
     */
    val latencyUs: Long,
    /**
     * The measured latency an installer entered, µs; it replaces
     * [`Self::latency_us`] when set.
     */
    val measuredLatencyUs: Long?,
    /**
     * Its alarms still on.
     */
    val alarms: Long,
)

/**
 * A room, with its lip-sync offset.
 */
data class LinkSystemRoom(
    /**
     * The model's id.
     */
    val id: String,
    /**
     * Its name.
     */
    val name: String,
    /**
     * Its own lip-sync offset, µs; none: the model's.
     */
    val lipSyncUs: Long?,
)

/**
 * A scene a recall can apply.
 */
data class LinkSystemScene(
    /**
     * The model's id: what [`DspiCore::link_system_recall`] takes.
     */
    val id: String,
    /**
     * Its name.
     */
    val name: String,
    /**
     * The scene sets the system mute (true) or clears it (false); none:
     * leaves it.
     */
    val systemMute: Boolean?,
)

/**
 * An alarm still on (raised or acknowledged).
 */
data class LinkSystemAlarm(
    /**
     * The hub's id for it.
     */
    val id: Long,
    /**
     * `warning` or `critical`.
     */
    val severity: String,
    /**
     * The element's name it is about.
     */
    val subject: String,
    /**
     * The hub's sentence.
     */
    val message: String,
    /**
     * `raised` or `acknowledged`.
     */
    val state: String,
)

/**
 * The installation on the hub, as the System screen shows it.
 */
data class LinkSystemView(
    /**
     * The model's revision: what [`DspiCore::link_system_save`] is given back.
     */
    val revision: Long,
    /**
     * The hub has an installation (a model with at least one element).
     */
    val installed: Boolean,
    /**
     * This session's role on the hub now: `admin`, `control` or `viewer`.
     */
    val role: String,
    /**
     * The role may change the installation and write the link delays (admin).
     */
    val mayEdit: Boolean,
    /**
     * The role may recall scenes (control or admin).
     */
    val mayRecall: Boolean,
    /**
     * Why editing is not offered, or "".
     */
    val editNote: String,
    /**
     * Why recalling is not offered, or "".
     */
    val recallNote: String,
    /**
     * The system delay the alignment uses now, frames.
     */
    val systemDelayFrames: Long,
    /**
     * [`Self::system_delay_frames`] in ms.
     */
    val systemDelayMs: Double,
    /**
     * The model fixes no system delay: the hub takes the smallest every
     * unit takes.
     */
    val systemDelayAuto: Boolean,
    /**
     * The link's rate, Hz.
     */
    val rateHz: Long,
    /**
     * The model's lip-sync offset, µs.
     */
    val lipSyncUs: Long,
    /**
     * Every element: senders, fan-outs, then units in the model's order.
     */
    val units: List<LinkSystemUnit>,
    /**
     * The rooms.
     */
    val rooms: List<LinkSystemRoom>,
    /**
     * The scenes.
     */
    val scenes: List<LinkSystemScene>,
    /**
     * Alarms still on, critical first.
     */
    val alarms: List<LinkSystemAlarm>,
    /**
     * A sender reports its system mute set (none: no sender reported).
     */
    val systemMute: Boolean?,
    /**
     * The frame a sender holds a scene for, when it holds one.
     */
    val pendingApplyFrame: Long?,
    /**
     * Units (not senders or fan-outs) locked.
     */
    val locked: Long,
    /**
     * Units in holdover.
     */
    val holdover: Long,
    /**
     * Units whose link delay is still to be written.
     */
    val pending: Long,
    /**
     * Units the model has, but those whose firmware has no audio link
     * (WP HWLK1F): "N of M locked" counts the units that can lock.
     */
    val unitCount: Long,
    /**
     * One line for a status indicator: "Audio link: 4 of 4 locked".
     */
    val summary: String,
    /**
     * The summary's meaning for its colour: `ok`, `warning`, `problem`, or
     * `none` without an installation.
     */
    val health: String,
    /**
     * The alignment's issues, in the hub's words.
     */
    val issues: List<String>,
    /**
     * The hub limits how often the status is read; this is the last view
     * again, not a fresh one.
     */
    val stale: Boolean,
)

/**
 * One room's lip-sync offset to set.
 */
data class LinkRoomLipSync(
    /**
     * The room's id.
     */
    val roomId: String,
    /**
     * µs; none: the model's own.
     */
    val lipSyncUs: Long?,
)

/**
 * One unit's measured latency to set.
