    /**
     * Change the system delay.
     */
    val setSystemDelay: Boolean,
    /**
     * The new system delay, frames; none: the smallest every unit takes.
     */
    val systemDelayFrames: Long?,
    /**
     * Rooms' lip-sync offsets.
